mod math;
mod string_utils;

pub use math::add;
pub use string_utils::reverse;

pub fn run() -> String {
    format!("{}+{}={}, rev({})={}", 2, 3, math::add(2, 3), "abc", string_utils::reverse("abc"))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn t_run() {
        assert_eq!(run(), "2+3=5, rev(abc)=cba");
    }

    #[test]
    fn t_math() {
        assert_eq!(add(2, 3), 5);
    }

    #[test]
    fn t_string_utils() {
        assert_eq!(reverse("abc"), "cba");
    }
}
